import 'react-native-reanimated'
import * as SplashScreen from 'expo-splash-screen'
import { useEffect, useState } from 'react'
import { ApolloProvider } from '@apollo/client'
import { createApolloClient } from '@anythingai/app/utils/apollo'
import { ThemeProvider } from '@anythingai/app/theme'
import { KeyboardProvider } from 'react-native-keyboard-controller'
import * as SecureStore from 'expo-secure-store'
import { AUTH_KEY } from '@anythingai/app/constants'
import { useAuthStore, useSpeechPermissionStore } from '@anythingai/app/stores'
import { Platform, StyleSheet, View } from 'react-native'
import { GestureHandlerRootView } from 'react-native-gesture-handler'
import { Toaster } from '@anythingai/app/sonner'
import Purchases from 'react-native-purchases'

import { LaunchDarklyProvider } from '@anythingai/app/utils/launch-darkly'
import { SafeAreaProvider } from 'react-native-safe-area-context'
import { UpgradePlanModal } from './screens/upgrade-plan'
import { PurchaseCreditsModal } from './screens/purchase-credits'

SplashScreen.setOptions({ duration: 500, fade: true })
SplashScreen.preventAutoHideAsync()

export function Provider({ children }: { children: React.ReactNode }) {
	const { isReady } = useAuthStore()
	const { init: initSpeechPermission } = useSpeechPermissionStore()

	const [client, setClient] =
		useState<Awaited<ReturnType<typeof createApolloClient>>>()

	useEffect(() => {
		SecureStore.getItemAsync(AUTH_KEY).then((rawAuth) => {
			useAuthStore.getState().init(rawAuth)
			createApolloClient().then(setClient)
		})
	}, [])

	useEffect(() => {
		if (isReady && client) {
			SplashScreen.hide()
		}
	}, [isReady, client])

	useEffect(() => {
		if (
			Platform.OS === 'ios' &&
			process.env.EXPO_PUBLIC_REVENUECAT_PROJECT_APPLE_API_KEY
		) {
			try {
				Purchases.setLogHandler(() => {})
				Purchases.configure({
					apiKey: process.env.EXPO_PUBLIC_REVENUECAT_PROJECT_APPLE_API_KEY
				})
			} catch (error) {
				console.warn('Error configuring Purchases:', error)
			}
		}
		initSpeechPermission()
	}, [])

	if (!isReady || !client) {
		return null
	}

	const ToasterOverlayWrapper = ({
		children
	}: {
		children: React.ReactNode
	}) => {
		return (
			<View pointerEvents="none" style={StyleSheet.absoluteFill}>
				{children}
			</View>
		)
	}

	return (
		<ApolloProvider client={client}>
			<LaunchDarklyProvider>
				<ThemeProvider>
					<GestureHandlerRootView style={{ flex: 1 }} pointerEvents="box-none">
						<KeyboardProvider>
							<SafeAreaProvider pointerEvents="box-none">
								{children}
								<Toaster ToasterOverlayWrapper={ToasterOverlayWrapper} />
								<UpgradePlanModal />
								<PurchaseCreditsModal />
							</SafeAreaProvider>
						</KeyboardProvider>
					</GestureHandlerRootView>
				</ThemeProvider>
			</LaunchDarklyProvider>
		</ApolloProvider>
	)
}
